Here is the commit message:
ibmvnic: handle inconsistent login with reset

Inconsistent login with the vnicserver is causing the device to be
removed. This does not give the device a chance to recover from error
state. This patch schedules a FATAL reset instead to bring the adapter
up.

Fixes: 032c5e82847a2 ("Driver for IBM System i/p VNIC protocol")
Signed-off-by: Dany Madden <drt@linux.ibm.com>
Signed-off-by: Lijun Pan <ljp@linux.ibm.com>
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is caused by the inconsistent login responses from the vnicserver, which leads to the device being removed instead of allowing it to recover from an error state. This behavior prevents the adapter from properly handling errors and recovering, resulting in device instability.

Here is the patch:

 static int handle_login_rsp(union ibmvnic_crq *login_rsp_crq,
 			    struct ibmvnic_adapter *adapter)
 {
 	struct device *dev = &adapter->vdev->dev;
 	struct net_device *netdev = adapter->netdev;
 	struct ibmvnic_login_rsp_buffer *login_rsp = adapter->login_rsp_buf;
 	struct ibmvnic_login_buffer *login = adapter->login_buf;
 	u64 *tx_handle_array;
 	u64 *rx_handle_array;
 	int num_tx_pools;
 	int num_rx_pools;
 	u64 *size_array;
 	int i;

 	dma_unmap_single(dev, adapter->login_buf_token, adapter->login_buf_sz,
 			 DMA_TO_DEVICE);
 	dma_unmap_single(dev, adapter->login_rsp_buf_token,
 			 adapter->login_rsp_buf_sz, DMA_FROM_DEVICE);

 	/* If the number of queues requested can't be allocated by the
 	 * server, the login response will return with code 1. We will need
 	 * to resend the login buffer with fewer queues requested.
 	 */
 	if (login_rsp_crq->generic.rc.code) {
 		adapter->init_done_rc = login_rsp_crq->generic.rc.code;
 		complete(&adapter->init_done);
 		return 0;
 	}

 	netdev->mtu = adapter->req_mtu - ETH_HLEN;

 	netdev_dbg(adapter->netdev, "Login Response Buffer:\n");
 	for (i = 0; i < (adapter->login_rsp_buf_sz - 1) / 8 + 1; i++) {
 		netdev_dbg(adapter->netdev, "%016lx\n",
 			   ((unsigned long int *)(adapter->login_rsp_buf))[i]);
 	}

 	/* Sanity checks */
 	if (login->num_txcomp_subcrqs != login_rsp->num_txsubm_subcrqs ||
 	    (be32_to_cpu(login->num_rxcomp_subcrqs) *
 	     adapter->req_rx_add_queues !=
 	     be32_to_cpu(login_rsp->num_rxadd_subcrqs))) {
 		dev_err(dev, "FATAL: Inconsistent login and login rsp\n");
-		ibmvnic_remove(adapter->vdev);
+		ibmvnic_reset(adapter, VNIC_RESET_FATAL);
 		return -EIO;
 	}
 	size_array = (u64 *)((u8 *)(adapter->login_rsp_buf) +
 		be32_to_cpu(adapter->login_rsp_buf->off_rxadd_buff_size));
 	/* variable buffer sizes are not supported, so just read the
 	 * first entry.
 	 */
 	adapter->cur_rx_buf_sz = be64_to_cpu(size_array[0]);

 	num_tx_pools = be32_to_cpu(adapter->login_rsp_buf->num_txsubm_subcrqs);
 	num_rx_pools = be32_to_cpu(adapter->login_rsp_buf->num_rxadd_subcrqs);

 	tx_handle_array = (u64 *)((u8 *)(adapter->login_rsp_buf) +
 				  be32_to_cpu(adapter->login_rsp_buf->off_txsubm_subcrqs));
 	rx_handle_array = (u64 *)((u8 *)(adapter->login_rsp_buf) +
 				  be32_to_cpu(adapter->login_rsp_buf->off_rxadd_subcrqs));

 	for (i = 0; i < num_tx_pools; i++)
 		adapter->tx_scrq[i]->handle = tx_handle_array[i];

 	for (i = 0; i < num_rx_pools; i++)
 		adapter->rx_scrq[i]->handle = rx_handle_array[i];

 	adapter->num_active_tx_scrqs = num_tx_pools;
 	adapter->num_active_rx_scrqs = num_rx_pools;
 	release_login_rsp_buffer(adapter);
 	release_login_buffer(adapter);
 	complete(&adapter->init_done);

 	return 0;
 }



